    def retranslateUi(self, SVM_para):
        _translate = QtCore.QCoreApplication.translate
        SVM_para.setWindowTitle(_translate("SVM_para", "支持向量机：参数设置"))
        self.pushButton.setText(_translate("SVM_para", "确认"))
        self.pushButton_2.setText(_translate("SVM_para", "取消"))
        self.label_3.setToolTip(_translate("SVM_para", "<html><head/><body><p>将数据映射到高维空间的函数，用于处理非线性问题。<span style=\" font-family:\'Courier New\';\">linear</span>（线性）, <span style=\" font-family:\'Courier New\';\">rbf</span>（径向基）, <span style=\" font-family:\'Courier New\';\">poly</span>（多项式）, <span style=\" font-family:\'Courier New\';\">sigmoid</span></p><p>。默认为 <span style=\" font-family:\'Courier New\';\">rbf</span>。模型性能的关键。线性可分或特征维度高时用<span style=\" font-family:\'Courier New\';\">linear</span>（速度快）；非线性问题优先尝试<span style=\" font-family:\'Courier New\';\">rbf</span>；特定领域（如文本）可能用<span style=\" font-family:\'Courier New\';\">poly</span>或<span style=\" font-family:\'Courier New\';\">sigmoid</span></p></body></html>"))
        self.label_3.setText(_translate("SVM_para", "kernel"))
        self.label_2_C.setToolTip(_translate("SVM_para", "<html><head/><body><p><span style=\" font-size:12pt;\">惩罚系数，平衡“分类间隔最大化”和“误分类点容忍度”。通常在对数尺度上搜索，如 </span><span style=\" font-family:\'Courier New\'; font-size:12pt;\">[0.01, 0.1, 1, 10, 100]</span><span style=\" font-size:12pt;\">控制过拟合与欠拟合。</span><span style=\" font-family:\'Courier New\'; font-size:12pt;\">C</span><span style=\" font-size:12pt;\">值越大，对误分类惩罚越重，模型越复杂，易过拟合；</span><span style=\" font-family:\'Courier New\'; font-size:12pt;\">C</span><span style=\" font-size:12pt;\">值越小，模型泛化能力越强，但可能欠拟合</span></p></body></html>"))
        self.label_2_C.setText(_translate("SVM_para", "C"))
        self.label_epsilon.setText(_translate("SVM_para", "epsilon"))
        self.label.setToolTip(_translate("SVM_para", "<html><head/><body><p><span style=\" font-size:12pt;\">指定用于训练的CPU核心数，用于并行计算以加速训练。</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039);\">-1</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">（使用全部核心），</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039);\">1</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">（默认，不并行），大于1的整数（指定核心数）</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; color:rgba(0,0,0,0.898039);\">显著减少训练时间</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">，特别在网格搜索或大数据集时。但并非核心数越多越好，需考虑内存消耗。</span></p></body></html>"))
        self.label.setText(_translate("SVM_para", "n_jobs"))
        self.label_random_state.setToolTip(_translate("SVM_para", "<html><head/><body><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">随机数种子，用于控制算法中所有随机性过程的可重复性。任意整数（如 </span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039);\">0</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">, </span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039);\">42</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">）。保证实验的</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:14px; color:rgba(0,0,0,0.898039);\">可重复性</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:14px; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">。设置固定值后，每次运行代码的结果（如数据洗牌、概率估计初始化）将完全一致</span></p></body></html>"))
        self.label_random_state.setText(_translate("SVM_para", "random_state"))
        self.label_4.setToolTip(_translate("SVM_para", "<html><head/><body><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">是否在训练SVM前对特征进行缩放（如标准化或归一化）。布尔值（</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039);\">True</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">/</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039);\">False</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">），但通常作为独立的预处理步骤。对于SVM，​</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Microsoft YaHei\'; font-size:12pt; color:rgba(0,0,0,0.898039);\">强烈建议进行特征缩放</span><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">​</span></p><p><span style=\" font-family:\'-apple-system,BlinkMacSystemFont,Segoe UI,PingFang SC,Roboto,Ubuntu,Helvetica Neue,Helvetica,Arial,Hiragino Sans GB,Microsoft YaHei UI,Microsoft YaHei,Source Han Sans CN,sans-serif\'; font-size:12pt; font-weight:400; color:rgba(0,0,0,0.898039); background-color:#ffffff;\">。这能确保所有特征在相同量纲上，避免某些特征因数值范围大而主导模型，从而提升模型性能与训练稳定性。</span></p></body></html>"))
